-- A (2026-10-11): truthful per-source reading status and enriched, source-backed
-- briefs for the Qatar Five prepared entities (fix-forward of 20261222093000).
--
-- Live bug: the card said "6 sources" although most were only discovered
-- links, and "tell me more" had almost nothing behind it. Each source now
-- carries a status (LINK_DISCOVERED, CONTENT_READ, FACT_EXTRACTED,
-- VERIFIED_AGAINST_SOURCE, BLOCKED_OR_UNAVAILABLE, NEEDS_REFRESH), a read
-- date and the verbatim excerpt that was read; each fact carries a topic,
-- a status and an as-of date. Quotes are kept only where the excerpt
-- stored beside them contains the text.
--
-- Additive and idempotent: new nullable columns, then upserts by key; the
-- facts are re-keyed by ordinal and nothing is deleted. The JSON document
-- is exactly `toPreparedUpsert(seed)` for scripts/seed/research/qatar-five.v1.json
-- (apps/q-api test `prepared-entity-seed.test.ts` fails if they drift).

alter table q_runtime.external_entity_sources
  add column if not exists status      text not null default 'LINK_DISCOVERED'
    check (status in ('LINK_DISCOVERED','CONTENT_READ','FACT_EXTRACTED','VERIFIED_AGAINST_SOURCE','BLOCKED_OR_UNAVAILABLE','NEEDS_REFRESH')),
  add column if not exists excerpt     text check (excerpt is null or length(excerpt) <= 1600),
  add column if not exists read_at     timestamptz,
  add column if not exists status_note text check (status_note is null or length(status_note) <= 400);

alter table q_runtime.external_entity_facts
  add column if not exists topic  text check (topic is null or length(topic) <= 40),
  add column if not exists status text not null default 'LINK_DISCOVERED'
    check (status in ('LINK_DISCOVERED','CONTENT_READ','FACT_EXTRACTED','VERIFIED_AGAINST_SOURCE','BLOCKED_OR_UNAVAILABLE','NEEDS_REFRESH')),
  add column if not exists as_of  text check (as_of is null or length(as_of) <= 40);

do $m$
declare
  doc jsonb := $j$[{"profileKey":"qa-demo-shadi-qishta","lastResearchedAt":"2026-10-11T00:00:00.000Z","facts":[{"claim":"According to his LinkedIn, finance and investment executive in Doha; the opening of his LinkedIn About text reads \"I am a strategic finance and investment executive with a track record of building…\" (cut off on the page).","sourceIds":["S03"],"evidenceClass":"PUBLICLY_REPORTED_UNCONFIRMED: not independently checked","topic":"ROLE","status":"FACT_EXTRACTED","asOf":null},{"claim":"According to his LinkedIn, his LinkedIn experience lists Midmac Contracting Company W.L.L. in Doha; the visible entries carry no titles or dates.","sourceIds":["S03"],"evidenceClass":"PUBLICLY_REPORTED_UNCONFIRMED: not independently checked","topic":"CAREER","status":"FACT_EXTRACTED","asOf":null},{"claim":"Reportedly, the Qatari Lens congratulated him on a new appointment as CEO Business Ventures at Midmac Contracting Company W.L.L. This comes from a third-party post, not from his own profile, so the current title is not confirmed.","sourceIds":["S06"],"evidenceClass":"PUBLICLY_REPORTED_UNCONFIRMED: not independently checked","topic":"CAREER","status":"FACT_EXTRACTED","asOf":null},{"claim":"According to his LinkedIn posts, his earlier posts speak for Supercell, \"a telecom company\", and tag #Supercellnetwork.","sourceIds":["S04","S05"],"evidenceClass":"PUBLICLY_REPORTED_UNCONFIRMED: not independently checked","topic":"CAREER","status":"FACT_EXTRACTED","asOf":null},{"claim":"In his LinkedIn post, on IFRS in Iraq he wrote that the Federal Board of Financial Supervision said adoption is optional for 2024 and mandatory from 2026, and argued it brings investor trust, clearer transparency and a chance to attract foreign investment. He says he has experience in auditing.","sourceIds":["S02"],"evidenceClass":"PUBLICLY_REPORTED_UNCONFIRMED: not independently checked","topic":"STATEMENT","status":"FACT_EXTRACTED","asOf":null},{"claim":"In his LinkedIn post, after a Nokia AI event in Dubai he listed four takeaways: AI is making telecom networks more intelligent, adaptive and efficient; it enables real-time decisions; its future depends on collaboration between operators, tech leaders and regulators; and continuous learning matters.","sourceIds":["S04"],"evidenceClass":"PUBLICLY_REPORTED_UNCONFIRMED: not independently checked","topic":"STATEMENT","status":"FACT_EXTRACTED","asOf":null},{"claim":"In his LinkedIn post, he posted about catching up with the Snoonu team and its CEO at Web Summit Qatar, describing Snoonu as a leading tech-driven delivery platform shaping e-commerce and last-mile delivery in the region.","sourceIds":["S05"],"evidenceClass":"PUBLICLY_REPORTED_UNCONFIRMED: not independently checked","topic":"STATEMENT","status":"FACT_EXTRACTED","asOf":null},{"claim":"Across the three of his own posts I read, the recurring topics are financial-reporting transparency, AI in telecom networks and Qatar's technology-led commerce. That is a pattern in the posts, not a stated investment mandate.","sourceIds":["S02","S04","S05"],"evidenceClass":"PUBLICLY_REPORTED_UNCONFIRMED: not independently checked","topic":"PRIORITIES","status":"FACT_EXTRACTED","asOf":null},{"claim":"A previous research note says a previous research note records that he emphasises consumer purchasing power as a real-world business indicator. I could not confirm this on a page I read.","sourceIds":["S03"],"evidenceClass":"PUBLICLY_REPORTED_UNCONFIRMED: not independently checked","topic":"PRIORITIES","status":"LINK_DISCOVERED","asOf":null}],"sources":[{"sourceId":"S01","url":"https://www.linkedin.com/in/shadi-qishta-282453a/","description":"Shadi Qishta public professional profile (search-indexed; direct access may require LinkedIn login)","publishedAt":null,"evidenceClass":"LinkedIn returned HTTP 999 to a plain request on 2026-10-11 (sign-in wall); text not read.","status":"BLOCKED_OR_UNAVAILABLE","excerpt":null,"readAt":null,"statusNote":"LinkedIn returned HTTP 999 to a plain request on 2026-10-11 (sign-in wall); text not read."},{"sourceId":"S02","url":"https://www.linkedin.com/posts/shadi-qishta-282453a_ifrs-transparency-comparability-activity-7282278544791982080-DSln","description":"Shadi Qishta on IFRS and transparent, comparable financial statements","publishedAt":null,"evidenceClass":"read 2026-10-11","status":"FACT_EXTRACTED","excerpt":"Iraq is taking a significant step forward in aligning its financial reporting practices with global standards by transitioning to International Financial Reporting Standards #IFRS … Federal Board of Financial Supervision In Iraq stated that implementation will be optional for 2024 but will become mandatory starting in 2026. … As someone with experience in auditing, I see this as a great opportunity for professionals to upskill and stay ahead in a rapidly evolving financial landscape.","readAt":"2026-10-11","statusNote":"Public LinkedIn post read 2026-10-11."},{"sourceId":"S03","url":"https://qa.linkedin.com/in/shadi-qishta-282453a","description":"Shadi Qishta public profile with comments on real purchasing power","publishedAt":null,"evidenceClass":"read 2026-10-11","status":"FACT_EXTRACTED","excerpt":"Page title: \"Shadi Qishta - الدوحة قطر | ملف شخصي احترافي | LinkedIn\". About (opening, truncated on the page): \"I am a strategic finance and investment executive with a track record of building…\". Experience entry: \"Midmac Contracting Company W.L.L.\" (Doha). Other entries showed locations only, without titles or dates.","readAt":"2026-10-11","statusNote":"Read 2026-10-11 through a page fetch; only the page title, an opening line of the About text (cut off on the page) and the employer name were visible."},{"sourceId":"S04","url":"https://www.linkedin.com/posts/shadi-qishta-282453a_ai-telecom-technology-activity-7291708172443017216-Z1Hb","description":"Shadi Qishta on AI, telecom networks and partnerships","publishedAt":null,"evidenceClass":"read 2026-10-11","status":"FACT_EXTRACTED","excerpt":"I had the pleasure of attending Nokia’s AI event in Dubai … As a telecom company, Supercell is always keen to stay ahead of emerging technologies … AI is redefining telecom networks, making them more intelligent, adaptive, and efficient. … The future of AI in telecom depends on collaboration between operators, tech leaders, and regulators.","readAt":"2026-10-11","statusNote":"Public LinkedIn post read 2026-10-11."},{"sourceId":"S05","url":"https://www.linkedin.com/posts/shadi-qishta-282453a_websummit-snoonu-qatar-activity-7300760342412906497-rBGL","description":"Shadi Qishta on Snoonu, ecommerce and logistics","publishedAt":null,"evidenceClass":"read 2026-10-11","status":"FACT_EXTRACTED","excerpt":"Great catching up with the Snoonu team and their visionary CEO, Hamad Mubarak Al-Hajri during the Web Summit Qatar … Snoonu has been making waves in the Qatari market as a leading tech-driven delivery platform","readAt":"2026-10-11","statusNote":"Public LinkedIn post read 2026-10-11."},{"sourceId":"S06","url":"https://www.linkedin.com/posts/the-qatari-lens_thearablens-theqatarilens-activity-7498733643109138433-fUsj","description":"Third-party Shadi Qishta CEO Business Ventures appointment mention; verify current date/title directly before public claim","publishedAt":null,"evidenceClass":"read 2026-10-11","status":"FACT_EXTRACTED","excerpt":"The Qatari Lens congratulates Shadi Qishta on his new appointment as CEO Business Ventures at Midmac Contracting Company W.L.L.","readAt":"2026-10-11","statusNote":"Third-party LinkedIn post read 2026-10-11; it is not his own statement."}],"quotes":[{"text":"As someone with experience in auditing, I see this as a great opportunity for professionals to upskill and stay ahead in a rapidly evolving financial landscape.","sourceId":"S02","speaker":"Shadi Qishta","date":null,"use":"SOURCE_QUOTE_ONLY"},{"text":"AI is redefining telecom networks, making them more intelligent, adaptive, and efficient.","sourceId":"S04","speaker":"Shadi Qish